// WF 20 v2 - Busca tickets recentes via API v1
// (cat_text vem vazio nesta build do GLPI 11; fallback no Extrair Dados deriva categoria do nome do form)
const helpers = this.helpers;
const baseV1 = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, skipSslCertificateValidation: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const r0 = await callRaw('GET', `${baseV1}/initSession`, {
  'App-Token': appToken, 'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { __debug: true, etapa: 'initSession_falhou', status: r0.status, body: r0.body }}];
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };

// Janela de 6h
const seisHorasAtras = new Date(Date.now() - 6*60*60*1000).toISOString().replace('T', ' ').substring(0, 19);

// searchOptions IDs: 2=id, 1=name, 7=category, 15=date_creation, 21=content, 12=status
const params = [
  'criteria[0][field]=15',
  'criteria[0][searchtype]=morethan',
  `criteria[0][value]=${encodeURIComponent(seisHorasAtras)}`,
  'forcedisplay[0]=2',
  'forcedisplay[1]=1',
  'forcedisplay[2]=7',
  'forcedisplay[3]=15',
  'forcedisplay[4]=21',
  'forcedisplay[5]=12',
  'range=0-99',
  'sort=15',
  'order=DESC'
].join('&');

const r = await callRaw('GET', `${baseV1}/search/Ticket?${params}`, H);
const data = (r.body && r.body.data) ? r.body.data : (Array.isArray(r.body) ? r.body : []);

await callRaw('GET', `${baseV1}/killSession`, H);

// Filtra os gerados por formulario (nome inicia com 'Solicitacao - ')
const result = [];
for (const t of data) {
  const name = t['1'] || '';
  if (!name.startsWith('Solicitacao - ')) continue;
  result.push({
    ticket_id: t['2'],
    name,
    cat_text: t['7'] || '',
    date_creation: t['15'],
    content: t['21'] || '',
    status: t['12']
  });
}

return result.map(t => ({ json: t }));

// Extrai dados do HTML do GLPI 11 Form Editor e normaliza para chaves esperadas pelo WF 14
// Busca o ticket original via source_ticket_id (passado pelo node 'Verifica se ja logado'),
// porque .item nao funciona aqui: o Filter + Postgres no caminho quebram o pairedItem tracking.
const sourceId = Number($input.first().json.source_ticket_id);
const t = $('Buscar Tickets Recentes').all().map(i => i.json).find(x => Number(x.ticket_id) === sourceId);
if (!t) throw new Error('Ticket original nao encontrado em Buscar Tickets Recentes para source_ticket_id=' + sourceId);
const html = t.content || '';

// Regex: <b>N) Label</b>: Valor<br>  (com tolerancia a espacos e variacoes)
const regex = /<b>\d+\)\s*([^<]+?)<\/b>\s*:\s*([\s\S]*?)(?=<br|<\/p|<h2)/g;
const dados = {};
let match;
while ((match = regex.exec(html)) !== null) {
  const label = match[1].trim();
  // Limpa o valor: remove tags HTML internas
  let valor = match[2].replace(/<[^>]+>/g, '').trim();
  // Normaliza label para chave
  const key = label.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (key && valor !== undefined) dados[key] = valor;
}

// Aliases: mapeia chaves longas/normalizadas para os nomes que o WF 14 espera
const aliasMap = {
