  'justificativa_para_criacao_do_e_mail_institucional': 'motivo_email',
  'novo_setor_de_destino': 'novo_setor',
  'novo_local_de_trabalho': 'novo_local'
};
for (const [k, alias] of Object.entries(aliasMap)) {
  if (dados[k] !== undefined && dados[alias] === undefined) {
    dados[alias] = dados[k];
  }
}

// Fallback heuristico: se ainda nao temos as chaves criticas, varre as chaves do form
// procurando por palavras-chave. Cobre mudancas futuras de label sem precisar atualizar aliasMap.
function _matchKey(allKeys, ...needles) {
  for (const k of allKeys) {
    if (needles.every(n => k.indexOf(n) !== -1)) return k;
  }
  return null;
}
const _todasChaves = Object.keys(dados);
if (dados.perfil_referencia === undefined) {
  const k = _matchKey(_todasChaves, 'perfil', 'referencia');
  if (k) dados.perfil_referencia = dados[k];
}
if (dados.email_superior === undefined) {
  const k = _matchKey(_todasChaves, 'superior');
  if (k) dados.email_superior = dados[k];
}

// Normaliza perfil_referencia para o login (username), nunca o nome completo.
// Se o GLPI gravar algo como 'Fulano de Tal (fulano.tal)', extrai o login entre parenteses;
