const helpers = this.helpers;
const baseV1 = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;

const item = $input.first().json;
const dados = item.dados_solicitacao || {};
const emailSuperior = (dados.email_superior || '').trim();
const catId = Number(item.category_id);
const ehAprovacao = [15, 16, 17, 18, 19, 20, 22].indexOf(catId) !== -1;

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, skipSslCertificateValidation: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}
function norm(s) { return String(s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }

let mobileRaw = '';
let lookupDebug = '';
let perfilDebug = '';
let H = null;

if (ehAprovacao) {
  try {
    const r0 = await callRaw('GET', `${baseV1}/initSession`, { 'App-Token': appToken, 'Authorization': `user_token ${userToken}` });
    if (r0.status === 200 && r0.body && r0.body.session_token) {
      H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };
    } else { lookupDebug = 'initSession_falhou'; }
  } catch (e) { lookupDebug = 'erro_init:' + String(e && e.message ? e.message : e); }
}

// 1) Mobile do superior (por email_superior)
if (H && emailSuperior) {
  try {
    const re = await callRaw('GET', `${baseV1}/UserEmail?searchText[email]=${encodeURIComponent(emailSuperior)}&range=0-50`, H);
    const arr = Array.isArray(re.body) ? re.body : (re.body && re.body.data ? re.body.data : []);
    let match = arr.find(u => (u.email || '').toLowerCase() === emailSuperior.toLowerCase());
    if (!match && arr.length) match = arr[0];
    const usersId = match ? match.users_id : null;
    if (usersId) {
      const ru = await callRaw('GET', `${baseV1}/User/${usersId}`, H);
      const u = ru.body || {};
      mobileRaw = u.mobile || u.phone || u.phone2 || '';
      if (!mobileRaw) lookupDebug = 'superior_sem_mobile_no_glpi';
    } else { lookupDebug = 'superior_nao_encontrado_por_email'; }
  } catch (e) { lookupDebug = 'erro:' + String(e && e.message ? e.message : e); }
}

// 2) perfil_referencia: nome completo (do dropdown do GLPI) -> login (campo name no GLPI)
if (H && dados.perfil_referencia) {
  const nome = String(dados.perfil_referencia).trim();
  if (/\s/.test(nome)) {
    try {
      const alvo = norm(nome);
      const partes = nome.split(/\s+/);
      async function buscar(campo, valor) {
        const r = await callRaw('GET', `${baseV1}/User?searchText[${campo}]=${encodeURIComponent(valor)}&range=0-100`, H);
        return Array.isArray(r.body) ? r.body : (r.body && r.body.data ? r.body.data : []);
      }
      function achar(cands) {
        for (const u of cands) {
          const fn = norm(u.firstname), rn = norm(u.realname);
          if (`${fn} ${rn}` === alvo || `${rn} ${fn}` === alvo) return u;
        }
        return null;
      }
      let cands = await buscar('realname', partes[partes.length - 1]);
      let achado = achar(cands);
      if (!achado) {
        cands = await buscar('firstname', partes[0]);
        achado = achar(cands);
        if (!achado && cands.length === 1) achado = cands[0];
      }
      if (achado && achado.name) { dados.perfil_referencia = achado.name; perfilDebug = 'resolvido:' + achado.name; }
      else { perfilDebug = 'nao_resolvido_mantido_nome'; }
    } catch (e) { perfilDebug = 'erro:' + String(e && e.message ? e.message : e); }
  } else { perfilDebug = 'ja_era_login'; }
}

if (H) { try { await callRaw('GET', `${baseV1}/killSession`, H); } catch (_) {} }

// Normaliza mobile -> +55DDDNUMERO
let digits = String(mobileRaw || '').replace(/\D/g, '');
let superiorWhatsapp = '';
if (digits.length === 10 || digits.length === 11) {
  superiorWhatsapp = '+55' + digits;
} else if ((digits.length === 12 || digits.length === 13) && digits.indexOf('55') === 0) {
  superiorWhatsapp = '+' + digits;
}

// Re-serializa dados (perfil_referencia pode ter virado login)
item.dados_solicitacao = dados;
item.dados_json = JSON.stringify(dados);

return [{ json: Object.assign({}, item, {
  superior_email: emailSuperior,
  superior_mobile_raw: mobileRaw,
  superior_whatsapp: superiorWhatsapp,
  eh_aprovacao: ehAprovacao,
  superior_lookup_debug: lookupDebug,
  perfil_debug: perfilDebug
}) }];

const helpers = this.helpers;
const cw = $('Carregar Tokens').first().json;
const base = String(cw.chatwoot_url || '').replace(/\/+$/, '');
const token = cw.chatwoot_token || '';
const ACCOUNT = 1;
const INBOX = 7;

const j = $input.first().json;
const phone = j.superior_whatsapp;
const ticketId = j.ticket_id;
const titulo = String(j.ticket_name || '').replace(/^Solicitacao - /, '');
const url = j.ticket_url;
const conteudo = '\u{1F4CB} Ha uma solicitacao aguardando sua aprovacao no GLPI.\n' +
  'Chamado #' + ticketId + ' - ' + titulo + '\n' +
  'Aprove em: ' + url;

async function cwApi(method, path, body) {
  const opts = { method, url: base + '/api/v1/accounts/' + ACCOUNT + path, headers: { 'api_access_token': token, 'Content-Type': 'application/json' }, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (body !== undefined) opts.body = JSON.stringify(body);
  const r = await helpers.httpRequest(opts);
  let b = r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (_) {} }
  return { status: r.statusCode || r.status, body: b };
}

const resultado = { ticket_id: ticketId, phone: phone };
if (!base || !token || !phone) {
  resultado.sucesso = false;
  resultado.erro = 'chatwoot_url/token ou telefone do superior ausente';
  return [{ json: resultado }];
}
try {
  let contactId = null;
  let sourceId = null;
  const s = await cwApi('GET', '/contacts/search?q=' + encodeURIComponent(phone));
  const found = (s.body && s.body.payload) ? s.body.payload : [];
  if (found.length) {
    contactId = found[0].id;
    const cis = found[0].contact_inboxes || [];
    const ci = cis.find(x => String((x.inbox && x.inbox.id) || x.inbox_id) === String(INBOX));
    if (ci) sourceId = ci.source_id;
  }
  if (!contactId) {
    const c = await cwApi('POST', '/contacts', { inbox_id: INBOX, name: phone, phone_number: phone });
    const p = (c.body && c.body.payload) ? c.body.payload : c.body;
    contactId = p && (p.contact ? p.contact.id : p.id);
    const ci = p && p.contact_inbox;
    if (ci) sourceId = ci.source_id;
  }
  if (contactId && !sourceId) {
    const ci = await cwApi('POST', '/contacts/' + contactId + '/contact_inboxes', { inbox_id: INBOX });
    sourceId = ci.body && (ci.body.source_id || (ci.body.payload && ci.body.payload.source_id));
  }
  const conv = await cwApi('POST', '/conversations', { source_id: sourceId, inbox_id: INBOX, contact_id: contactId });
  const convId = conv.body && (conv.body.id || (conv.body.payload && conv.body.payload.id));
  const msg = await cwApi('POST', '/conversations/' + convId + '/messages', { content: conteudo, message_type: 'outgoing' });
  resultado.sucesso = msg.status >= 200 && msg.status < 300;
  resultado.conversation_id = convId;
  resultado.contact_id = contactId;
  resultado.status_msg = msg.status;
} catch (e) {
  resultado.sucesso = false;
  resultado.erro = String(e && e.message ? e.message : e);
}
return [{ json: resultado }];
